class OnboardingRequest(BaseModel):
    """
    Request body for repository onboarding. The onboarding pipeline executes
    these steps in order: namespace, argocd_config, network_policies,
    status_registration, registry_credentials, domain_provisioning,
    postgres, app_role, generated_secrets, secrets, r2. Each step reports
    ok/failed/skipped in step_results. Generated credentials are summarised
    in the response's generated_credentials (names and actions, never values).

    """

    repo_full_name: str = Field(..., description="GitHub owner/repo (e.g. madfam-org/my-project)")
    project_name: str = Field(..., description="Project name for Enclii registration")
    namespace: str | None = Field(None, description="K8s namespace (defaults to project_name)")
    manifest_path: str | None = Field(
        None, description="Path to K8s manifests in the repo (default k8s/production)"
    )
    branch: str | None = Field("main", description="Branch to track")
    secret_name: str | None = Field(
        None, description="K8s Secret name (default <project>-credentials)"
    )
    provision_postgres: PostgresProvisionSpec | None = None
    provision_secrets: list[SecretEntry] | None = None
    provision_r2: R2ProvisionSpec | None = None
    provision_app_role: AppRoleSpec | None = None
    generate_secrets: list[GeneratedSecretSpec] | None = Field(
        None,
        description="Project-Secret keys whose values the server generates. Values are never returned.",
    )
    allow_netpol_narrowing: bool | None = Field(
        False,
        description="Let the network_policies step apply policies that narrow live\naccess: a podSelector {} made app-specific, an allowed port or\npeer a workload loses, or a new namespace-wide deny. Without it\nsuch a plan is refused, nothing is applied and the step fails.\nSee network_policy_plan in the response.\n",
    )


class NetworkPolicyPlan(BaseModel):
    """
    Diff between the live NetworkPolicies in the namespace and the ones
    generated from enclii.yaml, with the narrowing guard's findings.

    """

    namespace: str | None = None
    changes: list[NetworkPolicyChange] | None = None
    refusals: list[NetworkPolicyFinding] | None = Field(
        None, description="Changes refused without allow_netpol_narrowing."
    )
    warnings: list[str] | None = None
    notes: list[str] | None = Field(
        None,
        description="Inputs the guard could not read, such as a workload kind it could not list.",
    )
    workloads_checked: int | None = None
    blocked: bool | None = Field(
        None, description="The plan narrows live access and was (or would be) refused."
    )
    narrowing_allowed: bool | None = None
    applied: bool | None = None
    dry_run: bool | None = None
    diff: list[str] | None = Field(None, description="The plan rendered as lines.")


